item.content:encoded:
body:not(.page):not(.single):not(.woocommerce) .hentry {
    opacity: 1;
}
.main-navigation-container {
    width: 100%;
    padding: 15px;
}
.main-navigation-container {
    padding: 15px !important;
}
.main-navigation-container .custom-logo-link {
    width: 300px;
}
input[type=color], input[type=date], input[type=datetime-local], input[type=datetime], input[type=email], input[type=month], input[type=number], input[type=range], input[type=tel], input[type=text], input[type=time], input[type=url], input[type=week] {
    border-radius: 10px;
    height: 60px !important;
}
.category-7 header.page-header {
    display: none;
}
.category-8 header.page-header {
    display: none;
}

